import{_ as t,o as e,c as s,ag as r}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Data structures","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/data-structures.md","filePath":"admin-guide/web-ui/data-structures.md","lastUpdated":1786379412000}'),i={name:"admin-guide/web-ui/data-structures.md"};function o(l,a,n,c,d,u){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="data-structures" tabindex="-1">Data structures <a class="header-anchor" href="#data-structures" aria-label="Permalink to &quot;Data structures&quot;">​</a></h1><p>Data structures define the metadata schema for datasets — the set of variables, their types, and the valid values for each. They standardize how tabular data is documented and can link to <a href="./codelists.html">codelists</a> to constrain categorical variables to approved values.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Data structures list view showing name, agency, version, and status</em></p></div><h2 id="accessing-data-structures" tabindex="-1">Accessing data structures <a class="header-anchor" href="#accessing-data-structures" aria-label="Permalink to &quot;Accessing data structures&quot;">​</a></h2><p>Go to <strong>Settings → Data structures</strong> in the administrator menu.</p><h2 id="creating-a-data-structure" tabindex="-1">Creating a data structure <a class="header-anchor" href="#creating-a-data-structure" aria-label="Permalink to &quot;Creating a data structure&quot;">​</a></h2><ol><li>Click <strong>Add data structure</strong>.</li><li>Fill in: <ul><li><strong>Agency</strong> — the responsible organization</li><li><strong>Name</strong> — a unique identifier</li><li><strong>Version</strong> — semantic version number (e.g., <code>1.0.0</code>)</li></ul></li><li>Click <strong>Save</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Create data structure form</em></p></div><h2 id="managing-variables" tabindex="-1">Managing variables <a class="header-anchor" href="#managing-variables" aria-label="Permalink to &quot;Managing variables&quot;">​</a></h2><p>Each data structure contains a set of variable definitions. To manage variables:</p><ol><li>Open a data structure from the list.</li><li>Click <strong>Variables</strong>.</li><li>Add or edit variables. Each variable has: <ul><li><strong>Name</strong> — the variable identifier</li><li><strong>Type</strong> — the data type (text, numeric, date, etc.)</li><li><strong>Label</strong> — a human-readable description</li><li><strong>Value domain</strong> — optionally link a published codelist for categorical variables</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Variable editor within a data structure</em></p></div><h2 id="linking-codelists" tabindex="-1">Linking codelists <a class="header-anchor" href="#linking-codelists" aria-label="Permalink to &quot;Linking codelists&quot;">​</a></h2><p>When a codelist is set as the value domain for a variable, only codes from that codelist are considered valid for the variable. Ensure the codelist is in <strong>Published</strong> status before linking it.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>Data structures follow the same status workflow as codelists: Draft → Review → Published → Deprecated → Archived.</p>',16)])])}const m=t(i,[["render",o]]);export{g as __pageData,m as default};
